/**
 * Calculates the sum of prime numbers from the input array, 
 * where each prime number appears an even number of times.
 *
 * @param array $arr The input array of integers.
 *
 * @return int|null The sum of prime numbers if they appear an even number of times, null otherwise.
 */
function prod_signs(array $arr) {
    // Function to check if a number is prime
    function is_prime($n) {
        // Numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }

        // Check divisibility up to the square root of the number
        for ($i = 2; $i <= sqrt($n); $i++) {
            if ($n % $i == 0) {
                return false;
            }
        }

        return true;
    }

    // Get unique prime numbers from the input array
    $primes = array_filter(array_unique($arr), 'is_prime');

    // If no prime numbers are found, return null
    if (empty($primes)) {
        return null;
    }

    // Sum the prime numbers, counting each occurrence
    $sum = 0;
    foreach ($primes as $prime) {
        if (array_count_values($arr)[$prime] % 2 == 0) {
            $sum += $prime;
        } else {
            $sum -= $prime;
        }
    }

    return $sum;
}
