  return books.sort((book1, book2) => {
    // Check if book1 has numbers and book2 does not, or vice versa
    if (hasNumbers(book1) && !hasNumbers(book2)) return -1;
    if (!hasNumbers(book1) && hasNumbers(book2)) return 1;

    // Get the ASCII value of the first character of both book titles
    const char1 = book1[0];
