```rust
fn minimumCostPath(master: &mut GridMaster) -> i32 {
    let mut directions = ['U', 'D', 'L', 'R'];
    let mut queue = BinaryHeap::new();
    let mut visited = std::collections::BTreeSet::new();

    queue.push((0, 0, 0)); // cost, x, y
    while let Some((cost, x, y)) = queue.pop() {
        if visited.contains(&(x, y)) {
            continue;
        }
        visited.insert((x, y));

        if master.isTarget() {
            return cost;
        }

        for direction in &directions {
            if master.canMove(*direction) {
                let new_cost = cost + master.move(*direction);
                if new_cost != -1 {
                    queue.push((new_cost, x, y));
                }
            }
        }
    }

    -1
}

