    console.log(`The element ${searchElement} exists in the array.`);
} else {
    console.log(`The element ${searchElement} does not exist in the array.`);
}
```

But in this case, the `includes()` method will return `true` because the string "3" is a substring of the array, even though it's not exactly equal to any of the elements in the array. If you want to check for exact equality, you can use `indexOf()` instead:

```javascript
// Define the array
let array = [1, 2, 3, 4, 5, 5, 4, 3, 2, 1];

// Define the search element
let searchElement = "3";

// Check if the search element exists in the array
if (array.indexOf(searchElement) !== -1) {
    console.log(`The element ${searchElement} exists in the array.`);
} else {
    console.log(`The element ${searchElement} does not exist in the array.`);
}
```

This way, the `indexOf()` method will return `-1` if the element is not found in the array, instead of searching for it as a substring.

