function findSubstring(s: string; queries: TQuery): TQueryArray;
type
  TQuery = array[0..1] of Integer;
  TQueryArray = array of TQuery;

var
  n, idx, first, second, i, j, k, m, sum, ans, temp: Integer;
  arr: array of Integer;
  res: TQueryArray;

function XOR(a, b: Integer): Integer;
begin
  Result := a XOR b;
end

function binaryToDecimal(s: string): Integer;
var
  i, mul: Integer;
begin
  Result := 0;
  mul := 1;
  for i := Length(s) - 1 downto 0 do
  begin
    Result := Result + (Ord(s[i]) - Ord('0')) * mul;
    mul := mul * 2;
  end;
end

function findRange(const s: string; left, right: Integer): Integer;
var
  i: Integer;
  sum: Integer;
begin
  Result := 0;
  sum := 0;
  for i := left to right do
  begin
    sum := sum * 2 + Ord(s[i]) - Ord('0');
  end;
  Result := sum;
end

begin
  n := Length(queries);
  SetLength(res, n);
  for i := 0 to n - 1 do
  begin
    first := queries[i, 0];
    second := queries[i, 1];
    arr := [];
    idx := Length(s) - 1;
    sum := 0;
    while idx >= 0 do
    begin
      if (sum XOR first) = (binaryToDecimal(Copy(s, idx, Length(s) - idx)) XOR second) then
      begin
        SetLength(arr, Length(arr) + 1);
        arr[Length(arr) - 1] := idx;
        sum := sum * 2 + Ord(s[idx]) - Ord('0');
        idx := -1;
      end
      else if sum = (binaryToDecimal(Copy(s, idx, Length(s) - idx)) XOR second) then
      begin
        sum := sum * 2 + Ord(s[idx]) - Ord('0');
        Dec(idx);
      end
      else
      begin
        sum := sum * 2 + Ord(s[idx]) - Ord('0');
        Dec(idx);
      end;
    end;
    if Length(arr) > 1 then
      res[i] := [arr[0], Length(s) - 1]
    else if Length(arr) = 1 then
      res[i] := [arr[0], arr[0]]
    else
      res[i] := [-1, -1];
  end;
  Result := res;
end;

