    "author": "John Doe",
    "__v": 0
  },
  {
    "_id": "61d2a1fbd4d2c6b8a9e8f9a2",
    "title": "My Second Blog Post",
    "text": "This is my second blog post.",
    "author": "Jane Doe",
    "__v": 0
  }
]
```

