```java
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

/**
 * Caches the received thumbnail image.
 * @param fileInfo the information about the file
 * @param inputStream the input stream containing the thumbnail image data
 * @throws IOException if an I/O error occurs
 */
public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
    if (fileInfo == null || inputStream == null) {
        return;
    }

    // Create a HashMap to store the cached thumbnail images
    Map<String, byte[]> cache = new HashMap<>();

    // Generate a unique hash for the thumbnail image
    String imageHash = generateImageHash(inputStream);

    // Check if the image is already cached
    if (cache.containsKey(imageHash)) {
        System.out.println("Thumbnail image is already cached.");
        return;
    }

    // Cache the thumbnail image data
    byte[] imageData = readInputStream(inputStream);
    cache.put(imageHash, imageData);

    System.out.println("Thumbnail image cached successfully.");
}

/**
 * Generates a unique hash for the thumbnail image.
 * @param inputStream the input stream containing the thumbnail image data
 * @return the unique hash for the thumbnail image
 * @throws IOException if an I/O error occurs
 */
private static String generateImageHash(InputStream inputStream) throws IOException {
    try {
        // Create a MessageDigest instance
        MessageDigest messageDigest = MessageDigest.getInstance("MD5");

        // Read the input stream and update the message digest
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            messageDigest.update(buffer, 0, bytesRead);
        }

        // Reset the input stream
        inputStream.reset();

        // Generate the hash
        byte[] hashBytes = messageDigest.digest();
        StringBuilder hashBuilder = new StringBuilder();
        for (byte hashByte : hashBytes) {
            String hex = Integer.toHexString(0xff & hashByte);
            if (hex.length() == 1) {
                hashBuilder.append('0');
            }
            hashBuilder.append(hex);
        }

        return hashBuilder.toString();
    } catch (NoSuchAlgorithmException e) {
        throw new IOException("Failed to generate image hash", e);
    }
}

/**
 * Reads the input stream and returns the data as a byte array.
 * @param inputStream the input stream to read
 * @return the data as a byte array
 * @throws IOException if an I/O error occurs
 */
private static byte[] readInputStream(InputStream inputStream) throws IOException {
    ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
    byte[] buffer = new byte[1024];
    int bytesRead;
    while ((bytesRead = inputStream.read(buffer)) != -1) {
        byteArrayOutputStream.write(buffer, 0, bytesRead);
    }
    return byteArrayOutputStream.toByteArray();
}
```

