### Translated Code

Here's the Swift equivalent of the provided Python code:
```swift
func allSubstrings(inputString: String) -> [String] {
    let length = inputString.count
    var substrings: [String] = []
    for i in 0..<length {
        for j in (i + 1)...length {
            let substring = String(inputString[inputString.index(inputString.startIndex, offsetBy: i)..<inputString.index(inputString.startIndex, offsetBy: j)])
            substrings.append(substring)
        }
    }
    return substrings
}

func longestSubstring(strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else { return nil }
    var longestStr: String = ""
    for string in strings {
        let substrings = allSubstrings(inputString: string)
        for substring in substrings {
            let count = strings.filter { $0.contains(substring) }.count
            if count >= k && (longestStr.isEmpty || substring.count > longestStr.count) {
                longestStr = substring
            }
        }
    }
    return longestStr.isEmpty ? nil : longestStr
}
```
