```javascript
function sortBooks(books) {
    return books.sort((a, b) => {
        if (a[0] < b[0]) return -1;
        if (a[0] > b[0]) return 1;
        if (a.length > b.length) return -1;
        if (a.length < b.length) return 1;
        if (a.charCodeAt(0) > b.charCodeAt(0)) return -1;
        if (a.charCodeAt(0) < b.charCodeAt(0)) return 1;
        return 0;
    });
}

