**Solution:**

```objectpascal
function FindSubstring(s: string; queries: array of array of integer): array of array of integer;
var
  n: integer;
  i, j: integer;
  first, second: integer;
  val: integer;
  left, right: integer;
  result: array of array of integer;
  temp: integer;
  count: integer;
  hash: array of Integer;
begin
  n := Length(s);
  SetLength(result, Length(queries));
  SetLength(hash, n + 1);

  // Create a hash map of substrings and their decimal values
  For i := 0 to n - 1 Do
  Begin
    val := 0;
    For j := i to n - 1 Do
    Begin
      val := val * 2 + Ord(s[j]) - Ord('0');
      hash[j + 1] := val;
    End;
  End;

  For i := 0 to High(queries) Do
  Begin
    first := queries[i][0];
    second := queries[i][1];
    left := -1;
    right := -1;
    count := 0;

    For j := 0 to n Do
    Begin
      val := hash[j + 1] xor first;
      If val = second Then
      Begin
        If left = -1 Then
          left := j;
        right := j;
        count := count + 1;
      End
      Else
        If val > second Then
          Break;
    End;

    If count > 0 Then
      result[i] := [left, right]
    Else
      result[i] := [-1, -1];
  End;

  FindSubstring := result;
end;
```
