    let length = inputString.count
    return (0..<length).flatMap { i in
        (i..<length).map { j in
            return String(inputString[i...j])
        }
    }
}

/// Finds the longest substring that appears in at least k strings.
///
/// - Parameter strings: An array of strings to search for substrings.
/// - Parameter k: The minimum number of strings a substring must appear in.
/// - Returns: The longest substring that meets the condition, or nil if no such substring exists.
func longestSubstring(_ strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else { return nil }
    var longestStr = ""

    for s in strings {
        for substr in allSubstrings(s) {
            let count = strings.filter { $0.contains(substr) }.count
            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }

    return longestStr.isEmpty ? nil : longestStr
}
