```javascript
function customComparator(book1, book2) {
  // Check if both books start with a number or a letter
  let num1 = isNumber(book1);
  let num2 = isNumber(book2);

  // If one book starts with a number and the other with a letter, the number book comes first
  if (num1 !== num2) {
    return num1 ? -1 : 1;
  }

  // If both books start with a number or a letter, compare their starting letters
  let start1 = book1[0];
  let start2 = book2[0];
  if (start1 !== start2) {
    return start1.localeCompare(start2);
