function sortBooks(books) {
    return books.slice().sort((a, b) => {
        // Check if the first character of both books is a digit
        const isDigitA = /^\d/.test(a);
        const isDigitB = /^\d/.test(b);

        // If both are digits, compare them as strings
        if (isDigitA && isDigitB) {
            return a.localeCompare(b);
        }

        // If one is a digit and the other is not, prioritize the digit
        if (isDigitA) return -1;
        if (isDigitB) return 1;

        // Compare the first character of both books
        const charA = a[0];
        const charB = b[0];

        // If the first characters are different, compare them
        if (charA !== charB) return charA.localeCompare(charB);

        // If the first characters are the same, compare the lengths of the books
        const lengthA = a.length;
        const lengthB = b.length;

        // If the lengths are different, compare them in descending order
